function backendPayload(payload={}){
  const out={...payload};
  if(out.serverId!==undefined&&out.tablegateId===undefined)out.tablegateId=out.serverId;
  if(out.targetServerId!==undefined&&out.targetTablegateId===undefined)out.targetTablegateId=out.targetServerId;
  if(out.serverIds!==undefined&&out.tablegateIds===undefined)out.tablegateIds=out.serverIds;
  delete out.serverId;delete out.targetServerId;delete out.serverIds;
  return out;
}
function backendResponse(alias,data){
  if(alias==='createServer')return {...data,server:data?.tablegate||data?.server};
  if(alias==='getServer')return {...data,server:data?.tablegate||data?.server};
  if(alias==='listOwnedCharacters')return {characters:Array.isArray(data)?data:(data?.characters||[])};
  if(alias==='previewInvite'&&data?.tablegate)return {...data,server:data.tablegate};
  if(alias==='pollEvents'&&data?.events){return {...data,events:data.events.map(event=>({...event,eventType:String(event.eventType||'').replace(/^TABLEGATE_/,'SERVER_'),audienceType:event.audienceType==='TABLEGATE'?'SERVER':event.audienceType}))}}
  return data;
}
async function rawBackendCall(action,payload={},auth=true){
  const body={action,...backendPayload(payload),userAgent:navigator.userAgent};
  if(auth&&State.token)body.token=State.token;
  let res,text,json;
  try{res=await fetch(CONFIG.backendUrl,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(body),redirect:'follow'});text=await res.text();json=JSON.parse(text)}
  catch(err){throw new ApiError('NETWORK_ERROR','Could not reach the TableGate backend.',String(err?.message||err))}
  if(!json?.ok)throw new ApiError(json?.error?.code||'API_ERROR',json?.error?.message||'The backend rejected the request.',json?.error?.details);
  return json.data;
}
function slotProjectName(kind){return `__TABLEGATE_SLOT_${String(kind).toUpperCase()}__`}
async function findSlotProject(kind,tablegateId,create=false){
  const list=await rawBackendCall('listProjects',{tablegateId});
  let project=(list||[]).find(item=>item.name===slotProjectName(kind));
  if(!project&&create)project=await rawBackendCall('createProject',{tablegateId,name:slotProjectName(kind),projectType:'TABLEGATE_SLOT',description:`TableGate synchronized ${kind} data.`,settings:{slotKind:kind,managedBy:'TableGate frontend'}});
  return project||null;
}
async function loadBackendSlot(kind,tablegateId,fallback){
  const project=await findSlotProject(kind,tablegateId,false);if(!project)return fallback;
  const detail=await rawBackendCall('getProject',{projectId:project.id});
  const chunks=(detail?.items||[]).filter(item=>item.itemType==='SLOT_CHUNK').sort((a,b)=>(+a.orderIndex||0)-(+b.orderIndex||0));
  if(!chunks.length)return fallback;
  try{return JSON.parse(chunks.map(item=>item.data?.chunk||'').join(''))}catch(_){return fallback}
}
async function saveBackendSlot(kind,tablegateId,value){
  const project=await findSlotProject(kind,tablegateId,true),serialized=JSON.stringify(value??null),size=28000;
  const chunks=[];for(let i=0;i<serialized.length;i+=size)chunks.push(serialized.slice(i,i+size));if(!chunks.length)chunks.push('null');
  const existing=await rawBackendCall('listProjectItems',{projectId:project.id});
  const old=(existing||[]).filter(item=>item.itemType==='SLOT_CHUNK').sort((a,b)=>(+a.orderIndex||0)-(+b.orderIndex||0));
  for(let i=0;i<chunks.length;i++){
    const payload={name:`${kind} chunk ${String(i+1).padStart(4,'0')}`,itemType:'SLOT_CHUNK',status:'ACTIVE',orderIndex:i,data:{chunk:chunks[i],slotKind:kind,index:i,total:chunks.length}};
    if(old[i])await rawBackendCall('updateProjectItem',{itemId:old[i].id,...payload});else await rawBackendCall('createProjectItem',{projectId:project.id,...payload});
  }
  for(let i=chunks.length;i<old.length;i++)await rawBackendCall('deleteProjectItem',{itemId:old[i].id});
  await rawBackendCall('updateProject',{projectId:project.id,settings:{slotKind:kind,chunkCount:chunks.length,characters:serialized.length,updatedAt:new Date().toISOString()}});
  return {saved:true,updatedAt:new Date().toISOString(),projectId:project.id,chunkCount:chunks.length};
}
function makeRecord(prefix,payload={}){return {id:`${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,9)}`,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),...payload}}
async function mutateCollectionSlot(kind,tablegateId,operation,payload,idKey){
  const list=await loadBackendSlot(kind,tablegateId,[]);let result;
  if(operation==='create'){result=makeRecord(kind.slice(0,4),payload);list.push(result)}
  else if(operation==='update'){const id=payload[idKey];const index=list.findIndex(item=>item.id===id);if(index<0)throw new ApiError('NOT_FOUND',`${kind} record not found.`);result={...list[index],...payload,updatedAt:new Date().toISOString()};list[index]=result}
  else if(operation==='delete'){const id=payload[idKey];const index=list.findIndex(item=>item.id===id);if(index>=0)list.splice(index,1);result={deleted:true,id}}
  await saveBackendSlot(kind,tablegateId,list);return result;
}
async function attachedSystems(tablegateId){
  const links=await rawBackendCall('listTablegateSystems',{tablegateId});
  return Array.isArray(links)?links:links?.systems||[];
}
function normalizeSystemDocument(doc,link){
  const meta=doc?.metadata||{};
  return {...doc,serverId:doc?.tablegateId||'',systemName:meta.systemName||link?.label||link?.system?.name||doc?.systemId||'',fileType:meta.fileType||doc?.documentType||'RULES_REFERENCE',mimeType:meta.mimeType||'',tags:Array.isArray(meta.tags)?meta.tags:[],extractionStatus:meta.extractionStatus||'STORED_ONLY',extractedText:meta.extractedText||''};
}
async function listAttachedSystemDocuments(tablegateId){
  const links=await attachedSystems(tablegateId),out=[];
  for(const link of links){
    const docs=await rawBackendCall('listSystemDocuments',{tablegateId,systemId:link.systemId});
    (Array.isArray(docs)?docs:docs?.documents||[]).forEach(doc=>out.push(normalizeSystemDocument(doc,link)));
  }
  return out;
}
async function resolveSystemLink(tablegateId,requestedName=''){
  const links=await attachedSystems(tablegateId),needle=String(requestedName||'').trim().toLowerCase();
  return links.find(link=>link.systemId===requestedName)||links.find(link=>String(link.label||link.system?.name||'').toLowerCase()===needle)||links.find(link=>link.isPrimary)||links[0]||{systemId:'sys_tablegate_generic',system:{name:'TableGate Generic'}};
}
async function createCompatibleSystemDocument(payload){
  const p=backendPayload(payload),tablegateId=String(p.tablegateId||State.server?.id||''),link=await resolveSystemLink(tablegateId,p.systemName||p.systemId);
  const metadata={...(p.metadata||{}),systemName:p.systemName||link.system?.name||link.label||'',fileType:p.fileType||p.documentType||'',mimeType:p.mimeType||'',tags:p.tags||[]};
  const doc=await rawBackendCall('createSystemDocument',{tablegateId,systemId:link.systemId,attachmentId:p.attachmentId,title:p.title,documentType:p.documentType||p.fileType||'RULES_REFERENCE',version:p.version||'',visibility:p.visibility||'TABLEGATE',metadata});
  return normalizeSystemDocument(doc,link);
}
async function virtualBackendAction(action,payload={}){
  const p=backendPayload(payload),tablegateId=String(p.tablegateId||State.server?.id||'');
  if(action==='getTablegateStudio')return {studio:await loadBackendSlot('studio',tablegateId,null),updatedAt:new Date().toISOString()};
  if(action==='saveTablegateStudio')return saveBackendSlot('studio',tablegateId,p.studio);
  if(action==='saveMapFoundry')return saveBackendSlot('map-foundry',tablegateId,p.data);
  if(action==='saveNpcLives')return saveBackendSlot('npc-lives',tablegateId,p.data);
  if(action==='saveCampaignCharacterVault')return saveBackendSlot('character-vault',tablegateId,p.vault);
  if(action==='getCampaignHubState')return loadBackendSlot('campaign-hub',tablegateId,null);
  if(action==='saveCampaignHubState')return saveBackendSlot('campaign-hub',tablegateId,p.state);
  if(action==='listCampaignAssets'){const list=await rawBackendCall('listAssets',{tablegateId,assetType:p.kind||p.assetType||'MAP',limit:500});return list||[]}
  if(action==='createCampaignAsset')return rawBackendCall('organizeAttachment',{attachmentId:p.attachmentId,assetType:p.kind||'MAP',title:p.title,tags:p.tags||[],metadata:{mimeType:p.mimeType,visibility:p.visibility,tablegateId}});
  if(action==='deleteCampaignAsset'){const assets=await rawBackendCall('listAssets',{tablegateId,limit:500});const asset=(assets||[]).find(item=>item.id===p.assetId);if(!asset)throw new ApiError('ASSET_NOT_FOUND','Campaign asset not found.');return rawBackendCall('deleteAttachment',{attachmentId:asset.attachmentId})}
  if(action==='broadcastDiceRoll')return rawBackendCall('rollDice',{channelId:p.channelId,expression:p.roll?.expression||'1d20',label:p.roll?.label||'Session roll',personaId:p.roll?.personaId||'',postMessage:false});
  if(action==='listOrganizerTasks')return loadBackendSlot('organizer-tasks',tablegateId,[]);
  if(action==='createOrganizerTask')return mutateCollectionSlot('organizer-tasks',tablegateId,'create',{...p,tablegateId,createdBy:State.user?.id||''},'taskId');
  if(action==='updateOrganizerTask')return mutateCollectionSlot('organizer-tasks',tablegateId,'update',p,'taskId');
  if(action==='deleteOrganizerTask')return mutateCollectionSlot('organizer-tasks',tablegateId,'delete',p,'taskId');
  if(action==='listCalendarItems')return loadBackendSlot('calendar-items',tablegateId,[]);
  if(action==='submitCalendarItem')return mutateCollectionSlot('calendar-items',tablegateId,'create',{...p,tablegateId,submittedBy:State.user?.id||'',approvalStatus:(hasPerm(PERM.ADMIN)||hasPerm(PERM.MANAGE_TABLEGATE))?'APPROVED':'PENDING'},'calendarItemId');
  if(action==='updateCalendarItem')return mutateCollectionSlot('calendar-items',tablegateId,'update',{...p,approvalStatus:p.approvalStatus||'PENDING'},'calendarItemId');
  if(action==='deleteCalendarItem')return mutateCollectionSlot('calendar-items',tablegateId,'delete',p,'calendarItemId');
  if(action==='approveCalendarItem'||action==='rejectCalendarItem')return mutateCollectionSlot('calendar-items',tablegateId,'update',{calendarItemId:p.calendarItemId,approvalStatus:action==='approveCalendarItem'?'APPROVED':'REJECTED',approvedBy:action==='approveCalendarItem'?(State.user?.id||''):'',rejectionReason:p.reason||''},'calendarItemId');
  if(action==='listRuleNotes')return loadBackendSlot('rule-notes',tablegateId,[]);
  if(action==='createRuleNote')return mutateCollectionSlot('rule-notes',tablegateId,'create',{...p,tablegateId,createdBy:State.user?.id||''},'noteId');
  if(action==='publishCampaignItems')return saveBackendSlot('published-items',tablegateId,p.items||[]);
  if(action==='unpublishCampaignItems'){const current=await loadBackendSlot('published-items',tablegateId,[]),remove=new Set((p.items||[]).map(item=>item.key));return saveBackendSlot('published-items',tablegateId,current.filter(item=>!remove.has(item.key)))}
  if(action==='askRulesAssistant'){
    const query=p.query||p.question||'',matches=await rawBackendCall('searchKnowledge',{tablegateId,query,limit:p.limit||6});
    const sources=(matches||[]).map(item=>({id:item.id,title:item.title,systemName:item.metadata?.system||item.metadata?.systemName||'',excerpt:item.snippet||'',score:item.score,sourceUrl:item.sourceUrl||''}));
    return {answer:sources.length?`Found ${sources.length} grounded backend knowledge match${sources.length===1?'':'es'}. Review the excerpts before applying a ruling.`:'No synchronized backend knowledge source matched this question. Use the embedded Knowledge Pack workspace to ingest the relevant files.',suggestedRoll:(String(query).match(/\b\d*d\d+(?:\s*[+\-]\s*\d+)?\b/i)||[])[0]||'',sources};
  }
  if(action==='reindexSystemDocument'){
    const docs=await listAttachedSystemDocuments(tablegateId),doc=docs.find(item=>item.id===p.documentId);
    if(!doc)return {id:p.documentId,extractionStatus:'STORED_ONLY',updatedAt:new Date().toISOString()};
    try{const parsed=await rawBackendCall('parseAttachment',{attachmentId:doc.attachmentId});return {...doc,extractionStatus:parsed?.result?.text?'INDEXED':'STORED_ONLY',extractedText:String(parsed?.result?.text||'').slice(0,250000),updatedAt:new Date().toISOString()}}
    catch(_){return {...doc,extractionStatus:'STORED_ONLY',updatedAt:new Date().toISOString()}}
  }
  throw new ApiError('UNKNOWN_ACTION','Unknown frontend compatibility action: '+action);
}
const API={
  async call(action,payload={},auth=true){
    if(BACKEND_VIRTUAL_ACTIONS.has(action))return virtualBackendAction(action,payload);
    const adapted=backendPayload(payload),tablegateId=String(adapted.tablegateId||State.server?.id||'');
    if(action==='listSystemDocuments'&&!adapted.systemId)return listAttachedSystemDocuments(tablegateId);
    if(action==='createSystemDocument'&&!adapted.systemId)return createCompatibleSystemDocument(adapted);
    const backendAction=BACKEND_ACTION_ALIASES[action]||action;
    const useAuth=auth!==false&&!BACKEND_PUBLIC_ACTIONS.has(backendAction);
    const data=await rawBackendCall(backendAction,adapted,useAuth);
    return backendResponse(action,data);
  }
};
const Store={get(k,f=null){try{const v=localStorage.getItem(`${CONFIG.storagePrefix}.${k}`);return v===null?f:JSON.parse(v)}catch{return f}},set(k,v){localStorage.setItem(`${CONFIG.storagePrefix}.${k}`,JSON.stringify(v))},del(k){localStorage.removeItem(`${CONFIG.storagePrefix}.${k}`)}};
