function avatarHtml(user,size='avatar'){const name=user?.username||user?.nickname||'Unknown';return `<span class="${size}">${user?.avatarDataUrl?`<img src="${esc(user.avatarDataUrl)}" alt="">`:esc(initials(name))}</span>`}
function roleColor(member){return [...(member?.roles||[])].sort((a,b)=>(+b.position||0)-(+a.position||0))[0]?.color||''}
function statusFor(userId){const p=State.presence.find(x=>x.userId===userId);return (p?.status||'OFFLINE').toLowerCase()}
function markdown(text){
  let s=esc(text||'');
  s=s.replace(/```([\s\S]*?)```/g,(_,x)=>`<pre><code>${x}</code></pre>`);
  s=s.replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>').replace(/~~([^~]+)~~/g,'<s>$1</s>');
  s=s.replace(/(^|\s)(https?:\/\/[^\s<]+)/g,(m,p,u)=>`${p}<a href="${u}" target="_blank" rel="noopener" style="color:#8dc4bd">${u}</a>`);
  s=s.replace(/@([A-Za-z0-9_. -]{2,32})/g,'<span class="mention">@$1</span>').replace(/\n/g,'<br>');return s;
}
function setView(view){$('#boot').classList.toggle('hidden',view!=='boot');$('#auth').classList.toggle('hidden',view!=='auth');$('#app').classList.toggle('hidden',view!=='app')}
function handleModalClose(e){if(e.target.matches('[data-close-modal]'))closeModal()}
function modal(title,body,foot='',large=false){const root=$('#modal-root');root.onclick=null;delete root.dataset.voiceRoom;root.removeEventListener('click',handleModalClose,true);root.addEventListener('click',handleModalClose,true);root.innerHTML=`<div class="modal-layer" data-close-modal><div class="modal ${large?'large':''}" role="dialog" aria-modal="true"><header class="modal-head"><h2>${esc(title)}</h2><button data-close-modal aria-label="Close">×</button></header><div class="modal-body">${body}</div>${foot?`<footer class="modal-foot">${foot}</footer>`:''}</div></div>`}
