function contextMenu(x,y,items){const root=$('#context-root');root.innerHTML=`<div class="context-menu" style="left:${Math.min(x,innerWidth-200)}px;top:${Math.min(y,innerHeight-280)}px">${items.map(i=>`<button data-key="${esc(i.key)}" class="${i.danger?'danger-text':''}">${esc(i.label)}</button>`).join('')}</div>`;root.onclick=e=>{const b=e.target.closest('button');if(!b)return;const item=items.find(i=>i.key===b.dataset.key);root.innerHTML='';item?.run()};setTimeout(()=>document.addEventListener('pointerdown',function h(e){if(!root.contains(e.target)){root.innerHTML='';document.removeEventListener('pointerdown',h)}},{once:false}),0)}
