  setView('boot');bindAuth();const pageUrl=new URL(location.href);const resetToken=pageUrl.searchParams.get('resetToken')||'';if(resetToken&&typeof window.openResetPassword==='function'){setView('auth');await window.openResetPassword(resetToken);return}const invite=pageUrl.searchParams.get('invite')||'';if(invite){$('#register-invite').value=invite;await previewInvite(invite)}
  try{State.health=await API.call('health',{},false);State.registrationMode=String(State.health?.registrationMode||'UNKNOWN').toUpperCase()}catch(err){setView('auth');$('#auth-error').textContent=err.message;$('#auth-error').classList.remove('hidden');return}
